changes.content:
networks:
    1panel-network:
        external: true
services:
    handbrake:
        container_name: ${CONTAINER_NAME}
        deploy:
            resources:
                limits:
                    cpus: ${CPUS}
                    memory: ${MEMORY_LIMIT}
        volumes:
            - ${CONFIG_PATH}:/config
        environment:
            - PUID=99
            - PGID=100
            - TZ=${TIME_ZONE}
            - CUSTOM_USER=${CUSTOM_USER}
            - PASSWORD=${PASSWORD}
            - TITLE=${TITLE}
            - SELKIES_UI_TITLE=${SELKIES_UI_TITLE}
            - DASHBOARD=${DASHBOARD}
            - LC_ALL=${LC_ALL}
            - NVIDIA_VISIBLE_DEVICES=${NVIDIA_VISIBLE_DEVICES}
            - NVIDIA_DRIVER_CAPABILITIES=${NVIDIA_DRIVER_CAPABILITIES}
            - NVIDIA_ENABLE=${NVIDIA_ENABLE}
        # NVIDIA GPU 设备 cgroup 规则(主设备号 195),容器内可访问 /dev/nvidia*
        # 195 = nvidia0/ctl/uvm 等所有 NVIDIA 字符设备
        # NVIDIA_ENABLE=true 时配合 NVIDIA Container Toolkit 方可真正使用 GPU
        device_cgroup_rules:
            - 'c 195:* rw'
        image: linuxserver/handbrake:1.11.2
        labels:
            createdBy: Apps
        networks:
            - 1panel-network
        ports:
            - ${HOST_IP}:${PANEL_APP_PORT_HTTP}:3000
            - ${HOST_IP}:${PANEL_APP_PORT_HTTPS}:3001
        restart: always

networks:
    1panel-network:
        external: true
services:
    hindsight:
        container_name: ${CONTAINER_NAME}
        deploy:
            resources:
                limits:
                    cpus: ${CPUS}
                    memory: ${MEMORY_LIMIT}
        environment:
            - TZ=${TZ}
            - HINDSIGHT_API_LLM_PROVIDER=${HINDSIGHT_API_LLM_PROVIDER}
            - HINDSIGHT_API_LLM_API_KEY=${HINDSIGHT_API_LLM_API_KEY}
            - HINDSIGHT_API_LLM_MODEL=${HINDSIGHT_API_LLM_MODEL}
            - HINDSIGHT_API_LLM_BASE_URL=${HINDSIGHT_API_LLM_BASE_URL}
            - HINDSIGHT_API_EMBEDDINGS_PROVIDER=${HINDSIGHT_API_EMBEDDINGS_PROVIDER}
            - HINDSIGHT_API_EMBEDDINGS_OPENAI_API_KEY=${HINDSIGHT_API_EMBEDDINGS_OPENAI_API_KEY}
            - HINDSIGHT_API_EMBEDDINGS_OPENAI_BASE_URL=${HINDSIGHT_API_EMBEDDINGS_OPENAI_BASE_URL}
            - HINDSIGHT_API_EMBEDDINGS_OPENAI_MODEL=${HINDSIGHT_API_EMBEDDINGS_OPENAI_MODEL}
            - HINDSIGHT_API_RERANKER_PROVIDER=${HINDSIGHT_API_RERANKER_PROVIDER}
            - HINDSIGHT_API_DATABASE_URL=${HINDSIGHT_API_DATABASE_URL}
            - HINDSIGHT_API_HOST=${HINDSIGHT_API_HOST}
            - HINDSIGHT_API_PORT=${HINDSIGHT_API_PORT}
            - HINDSIGHT_ENABLE_CP=${HINDSIGHT_ENABLE_CP}
            - HINDSIGHT_CP_HOSTNAME=${HINDSIGHT_CP_HOSTNAME}
            - HINDSIGHT_CP_PORT=${HINDSIGHT_CP_PORT}
            - HINDSIGHT_CP_DATAPLANE_API_URL=${HINDSIGHT_CP_DATAPLANE_API_URL}
            - HINDSIGHT_CP_ACCESS_KEY=${HINDSIGHT_CP_ACCESS_KEY}
        image: ghcr.io/vectorize-io/hindsight:0.9.1
        labels:
            createdBy: Apps
        networks:
            - 1panel-network
        ports:
            - ${HOST_IP}:${PANEL_APP_PORT_HTTP}:8888
            - ${HOST_IP}:${PANEL_APP_PORT_ADMIN}:9999
        restart: always
        volumes:
            - ./data:/home/hindsight/.pg0

networks:
  1panel-network:
    external: true
services:
  perplexica:
    container_name: ${CONTAINER_NAME}
    deploy:
      resources:
        limits:
          cpus: ${CPUS}
          memory: ${MEMORY_LIMIT}
    environment:
    - PORT=3000
    - AI_PROVIDER=${AI_PROVIDER}
    - AI_MODEL=${AI_MODEL}
    - API_KEY=${API_KEY}
    - API_URL=${API_URL}
    - SIMILARITY_THRESHOLD=${SIMILARITY_THRESHOLD}
    - SEARXNG_API_URL=${SEARXNG_API_URL}
    image: itzcrazykns1337/vane:full-latest
    labels:
      createdBy: Apps
    networks:
    - 1panel-network
    ports:
    - ${HOST_IP}:${PANEL_APP_PORT_HTTP}:3000
    restart: always
    volumes:
    - ./data:/app/server/lib/db
